async def start_host(config):
    clients = {}
    for name, server_config in config["mcpServers"].items():
        try:
            clients[name] = await connect_and_initialize(server_config)
        except Exception as e:
            log.warning(f"server {name} failed to start: {e}")
    return clients  # session proceeds with whichever servers came up cleanly
